// Picks k random items from a stream of unknown length
export function sampleStream<T>(stream: Iterable<T>, k: number, rand = Math.random): T[] {
  const reservoir: T[] = [];
  let i = 0;
  for (const item of stream) {
    if (i < k) {
      reservoir.push(item);
    } else {
      // pick index in [0, i]
      const j = Math.floor(rand() * i);
      if (j < k) {
        reservoir[j] = item;
      }
    }
    i++;
  }
  return reservoir;
}
